presets.css:
/* ========== 粉白双层立体 · 点击涟漪终极版 ========== */

/* A. 全局变量（硬直角 + 立体配色） */

.device {

  --dress-wg-radius: 0px !important;

  --dress-app-ico-radius: 0px !important;

  --dress-desk-glass-border: transparent;

  --cherry: #FF4D6D;

  --cherry-deep: #C9184A;

  --shadow-pink: rgba(255, 170, 190, 0.7); 

  --dress-desk-glass: rgba(255, 255, 255, 0.1); 

  --dress-desk-glass-strong: rgba(255, 255, 255, 0.15); 

}

/* B. 桌面底图 & 状态栏 */

.desk {

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-9a399eeb-e0e9-4d9b-8de2-bbb42365a1e0.jpg');

  background-size: cover;

  background-position: center;

  background-color: #FFF5F8; 

}

.status {

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-e50f7788-5b67-4a7f-8c0c-cd80dde37227.jpg');

  background-size: cover;

  background-position: center;

  background-color: rgba(255, 255, 255, 0.6) !important;

  backdrop-filter: blur(8px) saturate(150%);

  -webkit-backdrop-filter: blur(8px) saturate(150%);

  color: #C9184A;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

  border-bottom: 1px solid #fff;

}

/* C. 小组件：透明果冻玻璃罩 + 硬白描边 */

.wg-profile, .wg-hero, .wg-note, .wg-quote, .wg-cd, .wg-custom, .tile.wg {

  border-radius: 0 !important;

  background: linear-gradient(145deg, rgba(255,255,255,0.35), rgba(255,220,230,0.15)) !important; 

  backdrop-filter: blur(2px);

  -webkit-backdrop-filter: blur(2px);

  color: #C9184A;

  box-shadow: 4px 4px 0 rgba(255, 255, 255, 0.4), 8px 8px 0 rgba(255, 182, 193, 0.3);

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

  font-weight: 600;

}

/* ========== D. 应用图标 & 底栏图标：包含最新"点击涟漪"动画 ========== */

.tile.app .ico, .dock-app-ico, .dock-app-empty {

  border-radius: 0 !important;

  background: linear-gradient(145deg, #FFFFFF, #FFEEF2);

  border: 4px solid #FFFFFF; 

  box-shadow: 

    0 0 0 4px #FFB6C1,                

    6px 6px 14px var(--shadow-pink),  

    -4px -4px 10px #FFFFFF,           

    inset 3px 3px 6px #FFFFFF,        

    inset -3px -3px 6px #FFC6D3;      

  transition: all 0.15s ease-in-out; 



  /* 核心：点击动画容器属性 */

  position: relative;

}

/* 点击涟漪特效（按下出现你提供的图标，放大消散） */

.tile.app .ico::after, .dock-app-ico::after {

  content: '';

  position: absolute;

  top: 50%; left: 50%;

  width: 100%; height: 100%;

  transform: translate(-50%, -50%) scale(0);

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-f28a50e6-2b80-415a-83e2-d1db7c0bdcce.png');

  background-size: cover;

  background-position: center;

  opacity: 0;

  pointer-events: none; /* 让特效穿透，不挡点击 */

  z-index: 999;

}

.tile.app:active .ico::after, .dock-app-ico:active::after {

  animation: tap-pop 0.5s ease-out forwards;

}

/* 涟漪放大消散动画 */

@keyframes tap-pop {

  0% { opacity: 0.9; transform: translate(-50%, -50%) scale(0.5); }

  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.6); }

}

/* 悬停微微上浮 */

.tile.app:hover .ico, .dock-app-ico:hover {

  transform: translateY(-3px); 

  box-shadow: 0 8px 16px rgba(255, 170, 190, 0.7), 0 -4px 8px #FFF;

}

/* 按压时凹陷回弹 */

.tile.app:active .ico, .dock-app-ico:active {

  transform: translateY(2px); 

  box-shadow: 0 0 0 4px #FFB6C1, inset 4px 4px 8px var(--shadow-pink), inset -4px -4px 8px #FFFFFF;

}

/* 图标文字 */

.tile.app span {

  color: #C9184A; 

  font-weight: 600;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

}

/* E. 底部和导航栏（底图）+ 底栏图标悬浮 */

.nav-dock, .foot {

  border-radius: 0 !important;

  border: 4px solid #FFFFFF;

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-ccc3279c-221c-4889-9303-debaf56e2ae3.jpg');

  background-size: cover;

  background-position: center;

  box-shadow: 0 0 0 4px #FFB6C1, 0 -6px 14px var(--shadow-pink);

}

.dock-app-ico:hover {

  transform: scale(1.1) translateY(-4px);

}

/* F. 抽屉 / 选择器（呼吸动效） */

@keyframes breathe {

  0%, 100% { box-shadow: 0 0 0 4px #FFB6C1, inset 4px 4px 8px rgba(255,170,190,0.7); }

  50% { box-shadow: 0 0 0 6px #FFD1DC, inset 2px 2px 4px rgba(255,170,190,0.5); }

}

.picker {

  border-radius: 0 !important;

  border: 4px solid #FFFFFF;

  background: rgba(255, 255, 255, 0.95);

  box-shadow: 0 0 0 4px #FFB6C1, 6px 6px 14px var(--shadow-pink), -4px -4px 10px #FFFFFF;

}

.picker .selected {

  border-radius: 0 !important;

  background: var(--cherry);

  color: #FFFFFF;

  text-shadow: none;

  animation: breathe 2s infinite ease-in-out;

}

/* G. 第一页中间灰块：加隐藏感粉白虚线框 */

.wg-custom {

  outline: 1px dashed rgba(255, 150, 170, 0.3);

  outline-offset: -5px;

  border: none !important;

}

/* 1. 引入高级粉白数码字体（手机支持则下载，不支持则用系统优雅字体） */

@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;800&display=swap');

.device, .tile.app span, .status, .wg-cd, .wg-note, .wg-hero {

  font-family: 'Poppins', 'MiSans', 'HarmonyOS Sans', sans-serif;

}

/* 2. 给图标增加"高光扫过"特效（待机时偶尔发光） */

.tile.app .ico {

  overflow: hidden; /* 防止光溢出 */

}

.tile.app .ico::before {

  content: '';

  position: absolute;

  top: -50%; left: -60%;

  width: 40%; height: 200%;

  background: linear-gradient(120deg, transparent, rgba(255,255,255,0.7), transparent);

  transform: rotate(25deg);

  animation: slide-shine 4s infinite; /* 4秒循环一次扫光 */

}

@keyframes slide-shine {

  0% { left: -60%; }

  20% { left: 150%; }

  100% { left: 150%; }

}

/* 3. 把原来的按压动画稍微改成"弹性回缩"，更像果冻数码产品 */

.tile.app .ico {

  transition: transform 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.2s;

}

/* ================= 终极高级特效 ================= */

/* 1. 图标悬停反色+弹性放大 */

.tile.app .ico {

  transition: all 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275); /* 弹性贝塞尔曲线 */

}

.tile.app:hover .ico {

  background: #C9184A; /* 悬停变深红底 */

  transform: translateY(-3px) scale(1.1); /* 上浮并放大 */

  border-color: #FFFFFF;

  box-shadow: 0 0 0 4px #FFB6C1, 8px 8px 16px rgba(201, 24, 74, 0.5), inset 3px 3px 6px rgba(255,255,255,0.3);

}

.tile.app:hover .ico * {

  filter: brightness(0) invert(1); /* 图标内部变白 */

}

/* 2. 大数字（时间/天数）渐变流光字体 */

.wg-cd, .wg-hero {

  color: transparent !important;

  background: linear-gradient(145deg, #FFFFFF, #FF4D6D, #C9184A);

  background-size: 200% 200%;

  -webkit-background-clip: text;

  background-clip: text;

  animation: gradient-move 3s linear infinite;

  /* 保留硬白描边防止看不清 */

  text-shadow: -2px -2px 0 #fff, 2px -2px 0 #fff, -2px 2px 0 #fff, 2px 2px 0 #fff !important; 

}

@keyframes gradient-move {

  0% { background-position: 0% 50%; }

  100% { background-position: 200% 50%; }

}

/* 3. 图标外框的"呼吸流光"特效（克制版） */

.tile.app .ico {

  animation: border-breathe 3s infinite ease-in-out;

}

@keyframes border-breathe {

  0%, 100% { box-shadow: 0 0 0 4px #FFB6C1, 6px 6px 14px var(--shadow-pink), inset 3px 3px 6px #fff; }

  50% { box-shadow: 0 0 0 6px #FFD1DC, 6px 6px 14px var(--shadow-pink), inset 3px 3px 6px #fff; }

}

/* 4. 每次进入桌面的错落弹跳入场动画（数码感爆棚） */

.tile.app {

  animation: bounce-in 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275) backwards;

}

/* 错落延迟：根据位置依次出场 */

.tile.app:nth-child(1) { animation-delay: 0.0s; }

.tile.app:nth-child(2) { animation-delay: 0.05s; }

.tile.app:nth-child(3) { animation-delay: 0.1s; }

.tile.app:nth-child(4) { animation-delay: 0.15s; }

.tile.app:nth-child(5) { animation-delay: 0.2s; }

.tile.app:nth-child(6) { animation-delay: 0.25s; }

.tile.app:nth-child(7) { animation-delay: 0.3s; }

.tile.app:nth-child(8) { animation-delay: 0.35s; }

.tile.app:nth-child(9) { animation-delay: 0.4s; }

.tile.app:nth-child(10) { animation-delay: 0.45s; }

.tile.app:nth-child(11) { animation-delay: 0.5s; }

.tile.app:nth-child(12) { animation-delay: 0.55s; }

@keyframes bounce-in {

  0% { opacity: 0; transform: translateY(20px) scale(0.8); }

  100% { opacity: 1; transform: translateY(0) scale(1); }

}
